using System;using System.IO;using System.Diagnostics;using F=SolidEdgeFramework;using D=SolidEdgeDraft;using TianGongCadSuite;
class TrainingViewProbe{[STAThread]static void Main(string[] args){if(Process.GetProcessesByName("TianGong").Length>0)throw new Exception("CAD running");F.Application app=null;D.DraftDocument doc=null;try{using(new OleFilter()){app=(F.Application)Activator.CreateInstance(Type.GetTypeFromProgID("SolidEdge.Application"));app.Visible=true;app.DisplayAlerts=false;doc=(D.DraftDocument)app.Documents.Open(Path.GetFullPath(args[0]));for(int i=1;i<=doc.Sheets.Count;i++){var s=doc.Sheets.Item(i);Console.WriteLine("SHEET slot="+i+" nativeIndex="+s.Index+" key="+s.Key+" section="+s.SectionType);for(int j=1;j<=s.DrawingViews.Count;j++){var v=s.DrawingViews.Item(j);Console.WriteLine("VIEW slot="+j+" index="+v.Index+" key="+v.Key+" sheetIndex="+((D.Sheet)v.Sheet).Index);var source=v.SourceDrawingView;if(source!=null)Console.WriteLine("SOURCE index="+source.Index+" key="+source.Key);}}}}finally{if(doc!=null)doc.Close(false);if(app!=null)app.Quit();}}}
